/**
 * The second wave of Fortress events: ten per region and ten anywhere. Each is
 * built around the Skills the first wave left idle (Search, Evaluate,
 * Navigation, Survival, Climb, Acrobatics, Silent Move, Inquiry, Invocation)
 * or barely touched (Charm, Command, Commerce, Security, Awareness,
 * Intimidate, Dodge), so a broad crew finds a use for everyone. Every event
 * keeps an option with no check, so none can soft-lock a run.
 *
 * `look` is the art subject for the event's vignette (scripts/export-art-spec.ts).
 */
import type { EventDef, Outcome } from './events.ts';

const say = (t: string): Outcome => ({ type: 'text', t });
const hurt = (pct: number, who: 'party' | 'one' = 'one'): Outcome => ({ type: 'damage', pct, who });
const mad = (n: number, who: 'party' | 'one' = 'one'): Outcome => ({ type: 'insanity', n, who });
const taint = (n: number, who: 'party' | 'one' = 'one'): Outcome => ({ type: 'corruption', n, who });
const meter = (delta: number): Outcome => ({ type: 'meter', delta });
const FIGHT: Outcome = { type: 'combat' };
const REVEAL: Outcome = { type: 'reveal' };

